// =============================================
// COURSE DETAILS PART 5 - Communication & Soft Skills
// =============================================
(function() {
  const existing = typeof COURSE_DETAILS !== 'undefined' ? COURSE_DETAILS : {};
  existing['com-pub'] = [
    {
      intro: 'Stage fright is one of the most common fears in the world — even seasoned speakers experience it. The key is not to eliminate it but to manage it. Understanding the physiological and psychological aspects of stage fright helps you transform nervous energy into powerful delivery.',
      objectives: ['Understand the physiology of stage fright', 'Reframe anxiety as excitement', 'Use breathing and preparation techniques to manage nerves', 'Build confidence through practice'],
      sections: [
        { heading: '1. Understanding Stage Fright', paragraphs: ['Stage fright (performance anxiety) is a natural stress response. Your body releases adrenaline, increasing heart rate, sweating, and trembling. This is the same "fight or flight" response that helped our ancestors survive. The problem is not the adrenaline — it is interpreting these sensations as fear rather than excitement.', 'Reframing is powerful. Instead of thinking "I am nervous," think "I am excited and ready." Research shows that reframing anxiety as excitement improves performance. The physical sensations are the same — only your interpretation changes.'], bullets: ['Stage fright is a natural stress response — adrenaline prepares you', 'Same physical sensations as excitement (increased heart rate, energy)', 'Reframe: "I am excited" instead of "I am nervous"', 'Reframing improves performance — research proven', 'Even top performers get nervous — they use it as fuel'] },
        { heading: '2. Preparation & Breathing', paragraphs: ['Thorough preparation is the best antidote to stage fright. Know your material inside and out. Practice your speech multiple times — aloud, in front of a mirror, or recorded. The more prepared you are, the less your brain has to worry about in the moment.', 'Breathing techniques calm the nervous system. Box breathing (inhale 4s, hold 4s, exhale 4s, hold 4s) activates the parasympathetic nervous system, reducing heart rate and tension. Practice this before going on stage and during pauses in your speech.'], bullets: ['Preparation: know your material thoroughly and practice aloud', 'Rehearse in front of a mirror and record yourself', 'Box breathing: inhale 4s, hold 4s, exhale 4s, hold 4s', 'Deep breathing activates the calming parasympathetic system', 'Arrive early to familiarize yourself with the space'] },
        { heading: '3. Building Confidence Gradually', paragraphs: ['Confidence comes from competence, and competence comes from practice. Start with small, low-stakes audiences — a friend, a small group, a recorded video. Gradually increase the audience size. Each success builds evidence for your brain that you can do this.', 'On the day: visualize success, arrive early, connect with audience members before starting, and remember that the audience wants you to succeed. They are not judging you — they are there to receive your message. Focus on serving them, not on yourself.'], bullets: ['Start small: practice with one person, then a small group', 'Record yourself: watch and note one thing to improve', 'Visualize success: imagine a confident, engaging delivery', 'Connect with audience members before starting', 'Focus on serving your audience, not on yourself', 'The audience wants you to succeed — they are on your side'] }
      ],
      keyPoints: ['Stage fright is normal — reframe it as excitement and energy', 'Thorough preparation builds confidence and reduces anxiety', 'Breathing techniques (box breathing) calm the nervous system', 'Build confidence gradually: start small, visualize success, focus on serving'],
      summary: 'Stage fright is a natural response that can be managed. By reframing anxiety as excitement, preparing thoroughly, using breathing techniques, and building confidence gradually, you can transform nervous energy into a powerful, engaging presence.'
    },
    {
      intro: 'A great speech has a clear structure that guides the audience from beginning to end. The classic structure — opening, body, and conclusion — provides a framework that makes your message memorable and impactful.',
      objectives: ['Structure a speech with a strong opening, body, and conclusion', 'Craft a hook that captures attention', 'Use storytelling to connect emotionally', 'End with a clear call to action'],
      sections: [
        { heading: '1. The Opening Hook', paragraphs: ['The first 30 seconds of your speech are critical. You need to capture attention, establish credibility, and preview what is coming. Open with a hook: a surprising statistic, a compelling question, a short story, or a bold statement.', 'Avoid starting with "Hello, my name is..." or generic introductions. Instead, dive straight into something that makes the audience sit up and pay attention. Your hook should be relevant to your message and your audience.'], bullets: ['First 30 seconds: capture attention immediately', 'Hook types: surprising statistic, question, story, bold statement', 'Establish credibility: why should they listen to you?', 'Preview: tell them what they will learn', 'Avoid generic: "Hello my name is..." is a lost opportunity'] },
        { heading: '2. The Body: 3 Key Points', paragraphs: ['The body of your speech should contain 3 main points. Three is the magic number — easy to remember, easy to structure, and satisfying for the audience. Each point should be a clear, distinct idea supported by evidence, examples, or stories.', 'Use signposting: "My first point is...", "This leads to my second point...", "Finally, my third point...". This guides the audience through your argument and makes it easy to follow. Transitions between points should be smooth and logical.'], bullets: ['3 key points: easy to remember and structure', 'Each point: clear idea + evidence + example/story', 'Signposting: "first," "second," "finally" guides the audience', 'Smooth transitions: logical connection between points', 'Use stories: narratives are more memorable than facts'] },
        { heading: '3. Conclusion & Call to Action', paragraphs: ['Your conclusion should do three things: summarize your key points, reinforce your main message, and end with a strong call to action. Tell the audience what you want them to think, feel, or do as a result of your speech.', 'End memorably. A powerful closing statement, a thought-provoking question, or a reference back to your opening hook creates a sense of closure. The final words of your speech are what the audience will remember most.'], bullets: ['Summarize: briefly recap your 3 key points', 'Reinforce: restate your main message', 'Call to action: what should the audience do?', 'End memorably: powerful statement, question, or callback to your hook', 'Final words are the most remembered — make them count'] }
      ],
      keyPoints: ['Open with a hook that captures attention in the first 30 seconds', 'Structure the body around 3 key points with signposting', 'End with a summary, reinforced message, and strong call to action', 'Your final words are what the audience remembers most'],
      summary: 'A well-structured speech guides the audience from opening hook to memorable conclusion. By crafting a strong opening, organizing around 3 key points, and ending with a compelling call to action, you deliver a message that resonates and inspires action.'
    },
    {
      intro: 'Your voice and body language are powerful tools that can make or break a presentation. How you say something is often more important than what you say. Mastering vocal variety and intentional body language elevates your delivery from good to unforgettable.',
      objectives: ['Use vocal variety: pace, pitch, and volume', 'Use pauses effectively for emphasis', 'Use natural, purposeful gestures', 'Build trust through eye contact'],
      sections: [
        { heading: '1. Vocal Variety', paragraphs: ['Monotone delivery is the fastest way to lose your audience. Vary your pace — speak faster to convey excitement, slower for emphasis or seriousness. Vary your pitch — a higher pitch conveys enthusiasm, a lower pitch conveys authority. Vary your volume — louder for emphasis, softer for intimacy.', 'Record yourself and listen for vocal variety. If you sound flat, practice exaggerating the variations. Over time, these variations become natural. The goal is to sound conversational and engaging, not like a robot reading from a script.'], bullets: ['Pace: fast for excitement, slow for emphasis', 'Pitch: higher for enthusiasm, lower for authority', 'Volume: louder for emphasis, softer for intimacy', 'Record yourself: check for vocal variety', 'Aim for conversational, not robotic'] },
        { heading: '2. The Power of Pauses', paragraphs: ['Pauses are one of the most powerful tools in a speaker\'s toolkit. A pause before a key word builds anticipation. A pause after a key point lets it land. A pause during a transition signals a shift. Silence is not awkward — it is powerful.', 'Many speakers rush through their content, afraid of silence. But pauses make you look confident and thoughtful. They give the audience time to process. Practice pausing — count to 2 or 3 in your head at key moments. The audience will perceive you as more polished and in control.'], bullets: ['Pause before: builds anticipation for a key word', 'Pause after: lets an important point land', 'Pause during transitions: signals a shift', 'Silence signals confidence, not awkwardness', 'Practice: count to 2-3 in your head at key moments'] },
        { heading: '3. Gestures & Eye Contact', paragraphs: ['Gestures should be natural and purposeful. Use open palms to show honesty and openness. Use counting gestures to list points. Use descriptive gestures to illustrate size, shape, or direction. Avoid nervous gestures (fidgeting, touching your face, crossing arms).', 'Eye contact builds trust and connection. Make eye contact with individuals throughout the room — hold it for 3-5 seconds per person. Do not sweep the room mechanically; instead, have genuine one-on-one moments with different audience members. This makes everyone feel included.'], bullets: ['Open palms: honesty and openness', 'Counting gestures: illustrate lists', 'Descriptive gestures: show size, shape, direction', 'Avoid: fidgeting, touching face, crossing arms', 'Eye contact: 3-5 seconds per person', 'One-on-one moments: connect with individuals throughout the room'] }
      ],
      keyPoints: ['Vocal variety (pace, pitch, volume) keeps the audience engaged', 'Pauses build anticipation, let points land, and signal confidence', 'Gestures should be natural, purposeful, and open', 'Eye contact builds trust and connection with the audience'],
      summary: 'Your voice and body are your most powerful delivery tools. By mastering vocal variety, using pauses strategically, and employing natural gestures and eye contact, you transform your presentation from a monologue into a genuine connection with your audience.'
    }
  ];
  existing['com-write'] = [
    {
      intro: 'Email is the backbone of professional communication. Writing clear, effective emails saves time, prevents misunderstandings, and projects professionalism. Every email you send is a reflection of your communication skills.',
      objectives: ['Write clear and professional email subject lines', 'Structure emails for readability', 'Adapt tone to the audience and context', 'Proofread before sending'],
      sections: [
        { heading: '1. Subject Lines & Structure', paragraphs: ['The subject line is the first thing recipients see — and often determines whether they open your email. Make it clear and specific: "Q3 Budget Report Attached" is better than "Update." Include key information: project name, action needed, and deadline if applicable.', 'Structure your email for easy scanning: a professional greeting, a clear purpose statement in the first paragraph, the body with supporting details (use bullet points for multiple items), and a clear call to action. End with a professional closing and signature.'], bullets: ['Subject line: clear, specific, includes key info', 'First paragraph: state the purpose of the email', 'Body: supporting details, bullet points for readability', 'Call to action: what do you need the recipient to do?', 'Closing: professional sign-off with contact info'] },
        { heading: '2. Tone & Professionalism', paragraphs: ['Match your tone to the context. Formal tone for external clients, senior leaders, and official communications. Semi-formal for colleagues and regular work communications. Avoid overly casual language (slang, emojis) in professional emails unless you know the recipient well.', 'Be concise but polite. Use "please" and "thank you." Avoid all caps (shouting), excessive exclamation marks, and emotional language. If you are writing about a difficult topic, take time to cool down before hitting send. Once sent, it cannot be unsent.'], bullets: ['Formal: external clients, senior leaders, official communications', 'Semi-formal: colleagues, regular work communications', 'Avoid: slang, all caps, excessive exclamation marks', 'Be concise but polite: "please" and "thank you"', 'Wait before sending difficult emails — cool down first'] },
        { heading: '3. Proofreading & Best Practices', paragraphs: ['Always proofread before sending. Read your email aloud — this catches awkward phrasing and typos. Check for: correct recipient, appropriate subject line, grammar and spelling, tone, and clarity of the call to action.', 'Best practices: reply within 24 hours, use CC sparingly, use BCC for mailing lists, avoid "Reply All" unless necessary, and keep attachments under 10MB. For long emails, include a summary at the top. When forwarding, add context about why you are forwarding.'], bullets: ['Proofread: read aloud to catch errors', 'Check: recipient, subject, grammar, tone, CTA', 'Reply within 24 hours', 'CC sparingly, avoid "Reply All"', 'Long emails: include a summary at the top'] }
      ],
      keyPoints: ['Clear subject lines and structured emails improve readability', 'Match tone to context: formal for external, semi-formal for colleagues', 'Be concise, polite, and professional — avoid emotional language', 'Always proofread before sending'],
      summary: 'Email is a fundamental professional skill. By writing clear subject lines, structuring your messages for readability, matching tone to the audience, and always proofreading, you communicate effectively and project professionalism in every message.'
    },
    {
      intro: 'Reports are a formal way to communicate findings, analysis, and recommendations. A well-structured report makes complex information accessible and actionable. Whether you are writing a business report, a research paper, or a project update, structure is key.',
      objectives: ['Structure a report with executive summary, findings, and recommendations', 'Write clearly and concisely for your audience', 'Use data visualizations effectively', 'Cite sources and maintain credibility'],
      sections: [
        { heading: '1. Report Structure', paragraphs: ['A standard report structure: Executive Summary (a brief overview of the purpose, key findings, and recommendations — often written last but placed first), Introduction (background, purpose, scope, methodology), Findings (the main body — organized logically with headings and subheadings), Analysis (interpretation of the findings, what they mean), and Recommendations (actionable next steps based on the analysis).', 'The executive summary is the most important part — many readers will only read this. It should stand alone and give the reader the full picture in 1-2 paragraphs.'], bullets: ['Executive summary: standalone overview of purpose, findings, recommendations', 'Introduction: background, purpose, scope, methodology', 'Findings: main body, logically organized', 'Analysis: interpretation of findings', 'Recommendations: actionable next steps'] },
        { heading: '2. Writing for Your Audience', paragraphs: ['Know your audience and write for them. A technical report for engineers uses different language than a business report for executives. Executives want conclusions and recommendations — they may not need the detailed methodology. Technical audiences want the data and methodology.', 'Use clear, concise language. Avoid jargon unless your audience expects it. Define acronyms on first use. Use active voice ("We analyzed the data" vs "The data was analyzed"). Short paragraphs and section headings improve scannability.'], bullets: ['Know your audience: executives want conclusions, technical want details', 'Use clear, concise language — avoid unnecessary jargon', 'Define acronyms on first use', 'Active voice: "We analyzed" vs "The data was analyzed"', 'Short paragraphs and headings improve scannability'] },
        { heading: '3. Data Visualization & Credibility', paragraphs: ['Charts and graphs make data more accessible. Choose the right chart type: bar charts for comparisons, line charts for trends, pie charts for proportions (use sparingly), and scatter plots for correlations. Label clearly, include units, and highlight the key insight.', 'Cite sources to maintain credibility. Use a consistent citation style (APA, MLA, Chicago) and include a references section. Data visualizations should have source citations too. A well-cited report demonstrates rigor and allows readers to verify your claims.'], bullets: ['Bar chart: comparisons', 'Line chart: trends over time', 'Pie chart: proportions (use sparingly)', 'Scatter plot: correlations', 'Label clearly, highlight key insights', 'Cite sources: consistent style, references section'] }
      ],
      keyPoints: ['Structure: executive summary, introduction, findings, analysis, recommendations', 'The executive summary is the most important part — write it for busy readers', 'Tailor language and detail to your audience', 'Use charts and citations to make data accessible and credible'],
      summary: 'Report writing is a structured skill. By organizing your content with a clear structure, writing for your audience, using data visualizations effectively, and citing sources, you create reports that inform, persuade, and drive action.'
    },
    {
      intro: 'Persuasive writing is the art of moving people to action. Whether you are writing a proposal, a marketing email, or a fundraising letter, the principles of persuasion help you craft messages that change minds and inspire action.',
      objectives: ['Apply the AIDA framework: Attention, Interest, Desire, Action', 'Focus on benefits, not features', 'Use social proof and urgency ethically', 'Write compelling calls to action'],
      sections: [
        { heading: '1. The AIDA Framework', paragraphs: ['AIDA is a classic copywriting framework: Attention (grab the reader\'s attention with a compelling headline, question, or statistic), Interest (build interest by explaining the relevance and value), Desire (create desire by showing how the solution benefits the reader — use benefits, not features), and Action (tell the reader exactly what to do next with a clear call to action).', 'AIDA works because it follows the natural progression of decision-making: awareness → interest → desire → action. Each stage builds on the previous one, guiding the reader toward the desired outcome.'], bullets: ['Attention: compelling headline, question, or statistic', 'Interest: explain relevance and value', 'Desire: benefits, not features — show how it helps', 'Action: clear, specific call to action', 'AIDA follows the natural decision-making progression'] },
        { heading: '2. Benefits vs Features', paragraphs: ['Features are what your product or idea HAS. Benefits are what it DOES for the reader. The difference is crucial: "Our software has 256-bit encryption" (feature) vs "Your data is protected from hackers" (benefit).', 'Always lead with benefits. The reader cares about what your offering does for THEM, not what it is. Translate every feature into a benefit. "10GB storage" (feature) becomes "Store thousands of photos without worrying about space" (benefit).'], bullets: ['Feature: what it HAS ("256-bit encryption")', 'Benefit: what it DOES for the reader ("Your data is protected")', 'Always lead with benefits', 'Translate every feature into a benefit', 'Focus on the reader\'s needs, not your product'] },
        { heading: '3. Social Proof, Urgency & Call to Action', paragraphs: ['Social proof shows that others have benefited — "Join 10,000+ satisfied customers" or "Recommended by industry experts." People are influenced by what others do. Use testimonials, case studies, and statistics ethically.', 'Urgency creates a reason to act now — limited-time offers, limited availability, or a deadline. Use urgency honestly; false urgency erodes trust. The call to action should be specific, clear, and easy to follow: "Click here to start your free trial" is better than "Get started."'], bullets: ['Social proof: testimonials, case studies, user numbers', 'Urgency: limited time, availability, or deadline — be honest', 'Call to action: specific, clear, easy to follow', 'Combine: benefit + social proof + urgency + CTA', 'Always be ethical — false urgency and fake proof destroy trust'] }
      ],
      keyPoints: ['AIDA framework: Attention, Interest, Desire, Action', 'Sell benefits, not features — translate features into reader value', 'Social proof and urgency increase persuasion — use them ethically', 'A clear, specific call to action is essential'],
      summary: 'Persuasive writing combines psychology and structure. By applying the AIDA framework, focusing on benefits, using social proof and urgency ethically, and crafting clear calls to action, you can write messages that truly move people to act.'
    }
  ];
  existing['com-team'] = [
    {
      intro: 'Teams are the building blocks of organizations. Understanding how teams form, the roles people play, and the norms that guide behavior helps you contribute more effectively to any team you join.',
      objectives: ['Understand Tuckman\'s stages of team development', 'Recognize different team roles', 'Create positive team norms', 'Leverage diversity for stronger outcomes'],
      sections: [
        { heading: '1. Tuckman\'s Stages', paragraphs: ['Teams go through predictable stages: Forming (members get to know each other, polite and cautious), Storming (conflicts arise as different opinions emerge — a critical phase), Norming (the team establishes norms, roles, and processes), Performing (the team works effectively toward goals), and Adjourning (the team disbands after completing the project).', 'Understanding these stages helps you be patient with the process. Storming is not a sign of failure — it is a sign of growth. Teams that work through storming emerge stronger. Leaders can facilitate by acknowledging the stage and guiding the team through it.'], bullets: ['Forming: polite, cautious, getting to know each other', 'Storming: conflicts emerge, different opinions — critical phase', 'Norming: establish norms, roles, and processes', 'Performing: effective collaboration toward goals', 'Adjourning: disband after completion', 'Storming is a sign of growth, not failure'] },
        { heading: '2. Team Roles', paragraphs: ['In effective teams, members take on different roles. Some are task-focused (organizing, tracking progress, ensuring quality), some are process-focused (facilitating, mediating, building consensus), and some are relationship-focused (supporting, encouraging, resolving conflicts).', 'A healthy team has a mix of these roles. The best teams are not full of leaders — they are full of people who understand their role and how it complements others. Encourage everyone to contribute their unique strengths and perspectives.'], bullets: ['Task roles: organizing, tracking, ensuring quality', 'Process roles: facilitating, mediating, building consensus', 'Relationship roles: supporting, encouraging, resolving conflict', 'Mix of roles: strong teams are balanced', 'Everyone contributes unique strengths'] },
        { heading: '3. Norms & Diversity', paragraphs: ['Norms are the unwritten rules of behavior in a team — how decisions are made, how disagreements are handled, how communication happens. Good norms are established early and intentionally: "We start meetings on time," "We disagree respectfully," "We listen before responding."', 'Diversity strengthens teams. Different perspectives, backgrounds, and thinking styles lead to better decisions and more innovative solutions. Inclusive teams — where everyone feels safe to speak up — outperform homogeneous ones. Psychological safety is the foundation of effective teamwork.'], bullets: ['Norms: unwritten rules of team behavior', 'Establish norms intentionally: punctuality, respect, communication', 'Diversity: different perspectives lead to better decisions', 'Inclusion: everyone feels safe to speak up', 'Psychological safety: the foundation of team effectiveness'] }
      ],
      keyPoints: ['Teams develop through stages: forming, storming, norming, performing, adjourning', 'Different team roles (task, process, relationship) are all valuable', 'Establish positive norms early and intentionally', 'Diversity and psychological safety strengthen team outcomes'],
      summary: 'Effective teamwork is built on understanding team dynamics. By recognizing the stages of team development, valuing different roles, establishing positive norms, and embracing diversity, you can contribute to teams that are productive, collaborative, and enjoyable.'
    },
    {
      intro: 'Communication is the lifeblood of any team. Clear, respectful communication prevents misunderstandings, builds trust, and ensures alignment. This lesson covers the essential communication skills every team member needs.',
      objectives: ['Communicate clearly and respectfully in teams', 'Practice active listening', 'Give and receive constructive feedback', 'Choose the right communication channel'],
      sections: [
        { heading: '1. Clear Communication', paragraphs: ['Clear communication starts with knowing what you want to say. Be specific, concise, and direct. Use "I" statements to express your perspective without blame: "I think we should consider..." instead of "You are wrong." Avoid assumptions — state your understanding and ask for confirmation.', 'In team settings, repeat key points and check for understanding. "To make sure we are aligned, my understanding is that we will..." This prevents misalignment and shows you are listening. Encourage questions and be open to being wrong.'], bullets: ['Be specific, concise, and direct', 'Use "I" statements: express your perspective without blame', 'Check for understanding: repeat and confirm', 'Encourage questions', 'Be open to being wrong'] },
        { heading: '2. Active Listening', paragraphs: ['Active listening means fully concentrating on what the speaker is saying, not just waiting for your turn to talk. It involves: giving your full attention (put away your phone), showing you are listening (nodding, eye contact), providing feedback (paraphrasing, asking questions), and deferring judgment (listening to understand, not to respond).', 'Paraphrasing is a powerful active listening tool: "So what I am hearing is that you are concerned about the timeline." This confirms you understood and makes the speaker feel heard. It also gives them a chance to correct any misunderstanding.'], bullets: ['Full attention: put away distractions', 'Non-verbal cues: nodding, eye contact', 'Paraphrase: "So what I am hearing is..."', 'Ask questions: clarify and dig deeper', 'Listen to understand, not to respond'] },
        { heading: '3. Choosing Channels & Feedback', paragraphs: ['Choose the right channel for your message: instant messages for quick questions, email for detailed information, video calls for complex discussions, and in-person meetings for sensitive topics or team building. Match the channel to the message\'s urgency and complexity.', 'Feedback should be constructive, specific, and timely. The SBI model: Situation (when it happened), Behavior (what was observed), Impact (the effect). "In yesterday\'s meeting (situation), when you interrupted Sarah (behavior), it discouraged her from sharing her idea (impact)." Frame feedback as a gift, not criticism.'], bullets: ['Quick questions: instant message', 'Detailed info: email', 'Complex discussion: video call', 'Sensitive topics: in-person', 'Feedback: SBI model — Situation, Behavior, Impact', 'Feedback is a gift — frame it constructively'] }
      ],
      keyPoints: ['Communicate clearly, concisely, and respectfully', 'Practice active listening: full attention, paraphrasing, asking questions', 'Match the communication channel to the message', 'Use the SBI model for constructive feedback'],
      summary: 'Team communication is a skill that can be learned and improved. By communicating clearly, listening actively, choosing the right channels, and giving constructive feedback, you build trust, prevent misunderstandings, and contribute to a positive team culture.'
    },
    {
      intro: 'Conflict is inevitable in any team — different perspectives, priorities, and personalities will clash. The goal is not to avoid conflict but to resolve it constructively. Handled well, conflict can strengthen relationships and lead to better outcomes.',
      objectives: ['Address conflicts early before they escalate', 'Focus on interests, not positions', 'Use "I" statements to express concerns', 'Seek win-win solutions'],
      sections: [
        { heading: '1. Address Conflicts Early', paragraphs: ['Unaddressed conflicts fester. Small disagreements grow into resentment, communication breaks down, and team performance suffers. The best time to address a conflict is when it first arises — not when it has escalated.', 'Approach the person directly and privately. Use a neutral, collaborative tone: "I noticed we had a disagreement in the meeting. I would like to understand your perspective better." Avoid accusatory language, and assume good intent. The goal is resolution, not winning.'], bullets: ['Address conflicts early — before they fester', 'Approach directly and privately', 'Use neutral, collaborative language', 'Assume good intent', 'Goal: resolution, not winning'] },
        { heading: '2. Interests vs Positions', paragraphs: ['Positions are what people say they want — "I want the budget for my project." Interests are WHY they want it — "I need the budget to meet my team\'s quarterly targets." Focusing on positions creates deadlock; focusing on interests opens up creative solutions.', 'Ask "why" questions to uncover interests: "Why is this deadline important to you?" or "What would a good outcome look like from your perspective?" Once you understand the underlying interests, you can find solutions that address both parties\' needs.'], bullets: ['Positions: what people SAY they want', 'Interests: WHY they want it', 'Focus on interests to find creative solutions', 'Ask "why" to uncover underlying interests', 'Address both parties\' needs for win-win outcomes'] },
        { heading: '3. "I" Statements & Win-Win Solutions', paragraphs: ['"I" statements express your feelings without blaming: "I feel frustrated when deadlines are missed because it affects my work" instead of "You always miss deadlines." This reduces defensiveness and opens the door to dialogue.', 'Seek win-win solutions that address both parties\' core interests. Brainstorm options together, evaluate them collaboratively, and agree on a path forward. Sometimes the best solution is a compromise; sometimes it is a creative third option neither party had considered.'], bullets: ['"I" statements: express feelings without blame', 'Reduces defensiveness and opens dialogue', 'Win-win: address both parties\' core interests', 'Brainstorm options together', 'Seek creative third options, not just compromise'] }
      ],
      keyPoints: ['Address conflicts early and directly, with a collaborative tone', 'Focus on interests (the why) not positions (the what)', 'Use "I" statements to express feelings without blame', 'Seek win-win solutions that address both parties\' needs'],
      summary: 'Conflict resolution is a vital team skill. By addressing issues early, focusing on underlying interests, using "I" statements, and seeking collaborative solutions, you can transform conflicts into opportunities for growth and stronger relationships.'
    }
  ];
  existing['com-lead'] = [
    {
      intro: 'Emotional Intelligence (EQ) is the ability to recognize, understand, and manage your own emotions and the emotions of others. Research shows that EQ is a stronger predictor of success than IQ in most professional contexts. It is the foundation of effective leadership, teamwork, and communication.',
      objectives: ['Understand the four components of EQ', 'Develop self-awareness and self-regulation', 'Practice empathy and social skills', 'Apply EQ in professional settings'],
      sections: [
        { heading: '1. The Four Components of EQ', paragraphs: ['Daniel Goleman\'s EQ model has four components: Self-Awareness (recognizing your emotions and their impact), Self-Regulation (managing your emotions, especially under pressure), Empathy (understanding others\' emotions and perspectives), and Social Skills (building relationships, influencing, and managing conflict).', 'The components build on each other. Self-awareness is the foundation — without it, you cannot regulate your emotions or understand others. Empathy enables social skills. Developing EQ is a lifelong journey of self-reflection and practice.'], bullets: ['Self-awareness: recognize your emotions and their impact', 'Self-regulation: manage emotions, especially under pressure', 'Empathy: understand others\' emotions and perspectives', 'Social skills: build relationships, influence, resolve conflict', 'Components build on each other — self-awareness first'] },
        { heading: '2. Self-Awareness & Self-Regulation', paragraphs: ['Self-awareness starts with paying attention to your emotional reactions. What triggers you? How do you typically respond? Journaling, mindfulness, and feedback from trusted colleagues can help you see patterns. The more you understand your reactions, the more control you have.', 'Self-regulation is about choosing your response. When you feel anger or frustration rising, pause. Take a deep breath. Count to 10. Ask yourself: "What is the best way to handle this?" Responding thoughtfully is always better than reacting impulsively.'], bullets: ['Self-awareness: notice your emotional patterns', 'Journaling and mindfulness: increase self-awareness', 'Seek feedback: others see patterns you miss', 'Self-regulation: pause before reacting', 'Respond thoughtfully, not impulsively'] },
        { heading: '3. Empathy & Social Skills', paragraphs: ['Empathy is understanding how others feel. It is not the same as agreeing — it is understanding. Practice active listening, ask questions about others\' perspectives, and validate their feelings: "That sounds really challenging." Empathy builds trust and deepens relationships.', 'Social skills are empathy in action: building rapport, influencing positively, resolving conflicts, inspiring others, and leading with emotional intelligence. The most effective leaders are those who combine high EQ with technical competence — people trust them and want to work with them.'], bullets: ['Empathy: understand, not necessarily agree', 'Active listening and questions: practice empathy', 'Validate feelings: "That sounds challenging"', 'Social skills: empathy in action', 'High EQ + competence = effective leadership'] }
      ],
      keyPoints: ['EQ has four components: self-awareness, self-regulation, empathy, social skills', 'Self-awareness is the foundation — understand your emotional patterns', 'Self-regulation is choosing your response, not reacting impulsively', 'Empathy builds trust; social skills put empathy into action'],
      summary: 'Emotional Intelligence is a learnable skill that predicts success more than IQ. By developing self-awareness, practicing self-regulation, cultivating empathy, and applying social skills, you build stronger relationships and become a more effective leader and teammate.'
    },
    {
      intro: 'Self-regulation is the ability to manage your emotions, thoughts, and behaviors in different situations. It is what separates a thoughtful response from a reactive outburst. In high-pressure environments, self-regulation is a superpower.',
      objectives: ['Pause before reacting to emotional triggers', 'Practice mindfulness for emotional balance', 'Manage stress with healthy habits', 'Respond vs react — choose your response'],
      sections: [
        { heading: '1. The Pause', paragraphs: ['The pause is the most powerful self-regulation tool. When you feel anger, frustration, or anxiety rising, stop. Do not respond immediately. Take a deep breath. Count to 5. This brief pause activates your prefrontal cortex (the thinking brain) and calms the amygdala (the emotional brain).', 'In that pause, you have a choice. You can react from emotion — which you may regret — or you can respond thoughtfully. The pause gives you the space to choose. With practice, the pause becomes a habit.'], bullets: ['The pause: stop before responding', 'Deep breath: activates the thinking brain', 'Count to 5: calms the emotional brain', 'React: emotional, often regretted', 'Respond: thoughtful, intentional, chosen'] },
        { heading: '2. Mindfulness & Stress Management', paragraphs: ['Mindfulness is paying attention to the present moment without judgment. Regular mindfulness practice (even 5 minutes daily) reduces stress, improves focus, and increases emotional regulation. It helps you notice your emotions without being controlled by them.', 'Beyond mindfulness, manage stress with healthy habits: regular exercise, adequate sleep, healthy eating, and social connection. When your baseline stress is lower, you have more capacity to regulate your emotions when challenges arise.'], bullets: ['Mindfulness: present moment awareness without judgment', '5 minutes daily: reduces stress, improves focus', 'Notice emotions without being controlled by them', 'Exercise, sleep, nutrition: lower baseline stress', 'Social connection: a buffer against stress'] },
        { heading: '3. Respond vs React', paragraphs: ['Reacting is automatic, emotional, and often impulsive. Responding is deliberate, thoughtful, and intentional. The difference is the pause. Reacting comes from the amygdala (fight or flight). Responding comes from the prefrontal cortex (rational thinking).', 'To respond effectively: recognize the trigger, pause, take a breath, identify your goal in the situation, and then choose your response. "What outcome do I want?" is a powerful question that shifts you from reaction to response.'], bullets: ['React: automatic, emotional, impulsive — amygdala', 'Respond: deliberate, thoughtful, intentional — prefrontal cortex', 'The pause is the difference between reacting and responding', 'Ask: "What outcome do I want?"', 'Choose your response based on your goals'] }
      ],
      keyPoints: ['The pause (deep breath, count to 5) is the most powerful self-regulation tool', 'Mindfulness practice reduces stress and improves emotional regulation', 'Healthy habits lower baseline stress, increasing your capacity to regulate', 'Responding is a deliberate choice; reacting is an automatic habit'],
      summary: 'Self-regulation is the skill of choosing your response. By pausing before reacting, practicing mindfulness, managing stress with healthy habits, and consciously choosing to respond rather than react, you gain control over your emotions and your outcomes.'
    },
    {
      intro: 'Social skills are the tools we use to interact and communicate with others effectively. They are empathy in action — the ability to build relationships, influence positively, and create connection. Strong social skills are essential for leadership, teamwork, and personal success.',
      objectives: ['Build rapport and trust with others', 'Influence positively through credibility', 'Lead with empathy and emotional intelligence', 'Manage conflicts and inspire others'],
      sections: [
        { heading: '1. Building Rapport & Trust', paragraphs: ['Rapport is a harmonious relationship characterized by mutual understanding and trust. It is built through: genuine interest in others (ask questions, listen actively), finding common ground (shared interests, experiences, or values), consistency (being reliable and keeping promises), and authenticity (being genuine, not trying to be someone you are not).', 'Trust is the foundation of all relationships. It is built slowly through consistent actions over time — and can be destroyed quickly by one breach. Be trustworthy: do what you say you will do, be honest, and admit mistakes.'], bullets: ['Genuine interest: ask questions, listen actively', 'Common ground: shared interests, experiences, values', 'Consistency: reliable, keep promises', 'Authenticity: be genuine, not a persona', 'Trust: built slowly through consistent actions'] },
        { heading: '2. Positive Influence', paragraphs: ['Influence is the ability to affect others\' thoughts, actions, and decisions. The most effective influence comes from credibility (expertise and trustworthiness), not authority. People are influenced by those they respect and trust.', 'To influence positively: lead by example (model the behavior you want to see), use logic and emotion (data appeals to the mind, stories appeal to the heart), build coalitions (find allies who share your vision), and be open to being influenced yourself. Influence is a two-way street.'], bullets: ['Credibility: expertise + trustworthiness = influence', 'Lead by example: model the behavior you want to see', 'Logic + emotion: data for the mind, stories for the heart', 'Build coalitions: find allies who share your vision', 'Be open to influence: influence is two-way'] },
        { heading: '3. Leading with Empathy', paragraphs: ['Empathetic leadership means understanding your team members\' perspectives, motivations, and challenges. It is not about being "soft" — it is about being smart. Employees who feel understood are more engaged, loyal, and productive.', 'Inspire others by connecting their work to a larger purpose. Help people see how their contributions matter. Recognize and celebrate achievements. Provide support during challenges. And create an environment where people feel safe to speak up, take risks, and grow.'], bullets: ['Empathetic leadership: understand perspectives and challenges', 'Not "soft" — smart: engaged employees are more productive', 'Connect work to purpose: help people see how they matter', 'Recognize and celebrate achievements', 'Psychological safety: people feel safe to speak up and grow'] }
      ],
      keyPoints: ['Rapport and trust are built through genuine interest, consistency, and authenticity', 'Influence comes from credibility, not authority — lead by example', 'Empathetic leadership is smart leadership — it drives engagement and performance', 'Inspire others by connecting their work to purpose and creating psychological safety'],
      summary: 'Social skills are the practical application of emotional intelligence. By building rapport, influencing through credibility, leading with empathy, and creating an environment of trust and purpose, you build relationships that enable personal and professional success.'
    }
  ];
  existing['com-negotiate'] = [
    {
      intro: 'Negotiation is not a battle — it is a conversation aimed at reaching an agreement that works for both parties. The right mindset is essential: collaborative, prepared, and focused on mutual benefit. This lesson covers the foundational mindset of effective negotiation.',
      objectives: ['Adopt a collaborative negotiation mindset', 'Prepare with your interests and alternatives', 'Define your walk-away point', 'Aim for win-win outcomes'],
      sections: [
        { heading: '1. Negotiation is a Conversation', paragraphs: ['Many people approach negotiation as a zero-sum game: one person wins, the other loses. This adversarial mindset leads to conflict and often leaves value on the table. A better approach: negotiation is a joint problem-solving conversation where both parties can win.', 'Collaborative negotiation (also called principled negotiation) focuses on interests, not positions. It separates the people from the problem. It generates options for mutual gain. And it insists on objective criteria. This approach builds relationships and leads to better outcomes.'], bullets: ['Negotiation is a conversation, not a battle', 'Zero-sum: one wins, one loses — adversarial', 'Collaborative: both can win — joint problem solving', 'Focus on interests, not positions', 'Separate the people from the problem'] },
        { heading: '2. Preparation: BATNA & Walk-Away', paragraphs: ['BATNA (Best Alternative to a Negotiated Agreement) is your best option if the negotiation fails. Knowing your BATNA gives you power — if the deal is worse than your alternative, you can walk away. Always know your BATNA before entering a negotiation.', 'Your walk-away point is the minimum acceptable outcome — the line you will not cross. It is based on your interests and your BATNA. Define it in advance, before emotions come into play. A clear walk-away point helps you negotiate confidently and avoid bad deals.'], bullets: ['BATNA: Best Alternative to a Negotiated Agreement', 'BATNA gives you power: know your best alternative', 'Walk-away point: minimum acceptable outcome', 'Define it in advance, before emotions take over', 'A clear walk-away point enables confident negotiation'] },
        { heading: '3. Win-Win Outcomes', paragraphs: ['A win-win outcome is one where both parties achieve their core interests. It does not mean both get everything they want — it means both get enough that they feel good about the agreement. Win-win agreements are more sustainable and build stronger relationships.', 'To find win-win solutions: share information about your interests, ask about theirs, brainstorm creative options, and look for trades (things that are low value to you but high value to them, and vice versa). The best deals are often discovered, not demanded.'], bullets: ['Win-win: both achieve core interests', 'Not equal — both feel good about the agreement', 'Share interests: information enables creative solutions', 'Brainstorm options: quantity before quality', 'Look for trades: low value to you, high value to them'] }
      ],
      keyPoints: ['Negotiation is a collaborative conversation, not a battle', 'Know your BATNA (best alternative) and walk-away point before negotiating', 'Define your interests, not just your positions', 'Win-win outcomes are sustainable and strengthen relationships'],
      summary: 'The negotiation mindset is the foundation of effective negotiation. By approaching it as a collaborative conversation, preparing with your BATNA and walk-away point, and aiming for win-win outcomes, you can negotiate confidently and build better agreements.'
    },
    {
      intro: 'Salary negotiation is one of the most important financial conversations you will have. It can affect your lifetime earnings by hundreds of thousands of dollars. Yet many people avoid it due to fear or lack of preparation. This lesson gives you the tools to negotiate your salary with confidence.',
      objectives: ['Research market rates for your role and level', 'Know your value and articulate it', 'Practice the salary conversation', 'Focus on total compensation, not just base salary'],
      sections: [
        { heading: '1. Research & Preparation', paragraphs: ['Before any salary conversation, research market rates for your role, level, and location. Use resources like Glassdoor, Levels.fyi, LinkedIn Salary, and industry reports. Know the range for your position — from the 25th percentile to the 75th percentile.', 'Also research the company: their financial health, recent funding, typical compensation packages, and how they position themselves in the market. This context helps you understand what is realistic and what arguments might resonate.'], bullets: ['Research market rates: Glassdoor, Levels.fyi, LinkedIn Salary', 'Know the range: 25th to 75th percentile for your role', 'Research the company: financial health, funding, culture', 'Context matters: startup vs public company, location', 'Prepare: know your numbers before the conversation'] },
        { heading: '2. Know Your Value', paragraphs: ['Salary is not about what you need — it is about the value you bring. Articulate your value with specific examples: projects you led, metrics you improved, problems you solved. Quantify your impact: "Increased revenue by 20%," "Reduced costs by $50K," "Led a team of 5."', 'Practice your value statement: "Based on my experience in [specific area], my track record of [specific achievements], and the market rate for this role, I am looking for a base salary of [number]." Be specific and confident. You are not asking — you are presenting your value.'], bullets: ['Value, not need: what you bring, not what you need', 'Quantify impact: percentages, dollars, scale', 'Practice your value statement', 'Be specific: state a number, not a range', 'Confidence: you are presenting your value, not asking for a favor'] },
        { heading: '3. Total Compensation & Practice', paragraphs: ['Salary is just one component of total compensation. Consider: bonus, equity (stock options or RSUs), benefits (health insurance, 401k match), vacation time, remote work flexibility, professional development budget, and other perks. Sometimes a lower base salary with better equity or benefits is the better deal.', 'Practice the conversation with a friend or in front of a mirror. The more you practice, the more natural it feels. Prepare for common responses: "That is above our budget" (ask about the range), "We need to think about it" (set a follow-up timeline), "What else is important to you?" (talk about total compensation).'], bullets: ['Total compensation: base + bonus + equity + benefits + perks', 'Consider the whole package, not just the base', 'Practice the conversation: with a friend, in a mirror', 'Prepare for common responses and objections', 'Follow up: set a timeline, keep the conversation going'] }
      ],
      keyPoints: ['Research market rates and company context before negotiating', 'Articulate your value with specific, quantified achievements', 'Consider total compensation, not just base salary', 'Practice the conversation and prepare for common responses'],
      summary: 'Salary negotiation is a skill that can be learned. By researching market rates, knowing and articulating your value, considering total compensation, and practicing the conversation, you can negotiate with confidence and earn what you are worth.'
    },
    {
      intro: 'Negotiation is not just for big salary discussions — it is a part of everyday life. From buying a car to negotiating with a vendor, from settling a disagreement with a partner to deciding where to eat dinner, negotiation skills are constantly useful.',
      objectives: ['Use anchoring to set the negotiation range', 'Ask questions to uncover interests', 'Offer trade-offs to create value', 'Build relationships for long-term success'],
      sections: [
        { heading: '1. Anchoring', paragraphs: ['Anchoring is a cognitive bias where the first number mentioned in a negotiation sets the reference point for the discussion. Whoever anchors first has an advantage. If you are selling, start high. If you are buying, start low — but be reasonable enough to be taken seriously.', 'When you receive an anchor, do not accept it immediately. Challenge it with data: "Based on my research, similar products are priced at X." Anchor your counter-offer. The final outcome will likely be closer to the first anchor than to the other party\'s starting point.'], bullets: ['Anchoring: the first number sets the reference point', 'Whoever anchors first has an advantage', 'Seller: start high; Buyer: start low', 'Be reasonable: extreme anchors undermine credibility', 'Challenge the anchor with data, then counter-anchor'] },
        { heading: '2. Questions & Trade-offs', paragraphs: ['Questions are your most powerful negotiation tool. They uncover interests, reveal constraints, and build understanding. "What is most important to you in this deal?" "What are your must-haves?" "What would an ideal outcome look like?" The more you understand the other party, the more creative your solutions can be.', 'Trade-offs create value. Look for things that are low cost to you but high value to the other party — and vice versa. "If I can deliver a week earlier, would you be able to increase the budget?" This turns a concession into a value exchange.'], bullets: ['Questions: uncover interests, constraints, and priorities', 'Ask: "What matters most to you?" "What is ideal?"', 'Understanding enables creative solutions', 'Trade-offs: low cost to you, high value to them', 'Turn concessions into value exchanges'] },
        { heading: '3. Relationships Matter', paragraphs: ['Negotiation is not a one-time transaction — it is part of an ongoing relationship. How you negotiate affects how people perceive you and whether they want to work with you again. A "win" that damages the relationship is not a win.', 'Approach every negotiation with the goal of preserving and strengthening the relationship. Be respectful, listen actively, and seek solutions that work for both parties. The best negotiators are firm on the issues but gentle on the people. They build trust that pays dividends over time.'], bullets: ['Relationships matter: one negotiation affects future interactions', 'A "win" that damages the relationship is a loss', 'Be respectful and listen actively', 'Firm on issues, gentle on people', 'Trust built in negotiation pays dividends over time'] }
      ],
      keyPoints: ['Anchoring sets the reference point — anchor first with a reasonable number', 'Use questions to uncover interests and constraints', 'Trade-offs create value — exchange what is low cost to you for high value to them', 'Preserve relationships — how you negotiate affects future interactions'],
      summary: 'Everyday negotiation is about using the right techniques in the moment. By anchoring effectively, asking questions, finding trade-offs, and prioritizing relationships, you can negotiate better outcomes in every area of life — from big purchases to daily decisions.'
    }
  ];
  existing['com-culture'] = [
    {
      intro: 'Cultural awareness is the foundation of effective cross-cultural communication. Culture shapes how people communicate, make decisions, build relationships, and perceive time and authority. Understanding these differences prevents misunderstandings and builds stronger global connections.',
      objectives: ['Understand what culture is and how it shapes behavior', 'Distinguish between high-context and low-context cultures', 'Recognize cultural dimensions that affect communication', 'Develop cultural self-awareness'],
      sections: [
        { heading: '1. What is Culture?', paragraphs: ['Culture is the shared set of values, beliefs, norms, and behaviors of a group of people. It is learned (not inherited), shared (not individual), and influences everything from communication style to decision-making.', 'Culture is like an iceberg: visible aspects (food, dress, language) are above the surface, while deeper values (attitudes toward time, authority, relationships, and risk) are below the surface. Misunderstandings often arise from the invisible parts of culture.'], bullets: ['Culture: shared values, beliefs, norms, behaviors', 'Learned, not inherited — passed down through generations', 'Iceberg model: visible (food, dress) and invisible (values, attitudes)', 'Misunderstandings come from invisible cultural differences', 'Cultural self-awareness: understanding your own cultural lens'] },
        { heading: '2. High-Context vs Low-Context', paragraphs: ['High-context cultures (Japan, China, Middle East, Latin America) rely heavily on implicit communication — context, non-verbal cues, and shared understanding. What is NOT said is often as important as what is said. Relationships are built before business. Messages are indirect.', 'Low-context cultures (US, Germany, Scandinavia, Switzerland) rely on explicit, direct communication. The message is in the words. Relationships are less important for initial business interactions. Messages are direct and clear. "Yes" means yes, "no" means no.'], bullets: ['High-context: implicit, indirect, relationship-first', 'High-context: non-verbal cues, what is NOT said matters', 'Low-context: explicit, direct, message in the words', 'Low-context: "yes" means yes, "no" means no', 'Adapt your communication style to the context'] },
        { heading: '3. Cultural Dimensions', paragraphs: ['Hofstede\'s cultural dimensions help understand differences: Power Distance (how comfortable people are with unequal power distribution — high in Asia, low in Scandinavia), Individualism vs Collectivism (individual achievement vs group harmony — US is individualist, Japan is collectivist), and Uncertainty Avoidance (how comfortable people are with ambiguity — high in Greece, low in Singapore).', 'Understanding these dimensions helps you adapt: use formal titles in high power distance cultures, emphasize group benefits in collectivist cultures, and provide clear structure in high uncertainty avoidance cultures.'], bullets: ['Power distance: high (Asia, Latin America) vs low (Scandinavia)', 'Individualism vs collectivism: US (individual) vs Japan (group)', 'Uncertainty avoidance: high (Greece) vs low (Singapore)', 'Adapt: formal titles, group benefits, clear structure', 'Cultural awareness is a skill — practice and learn'] }
      ],
      keyPoints: ['Culture is an iceberg — visible and invisible elements shape behavior', 'High-context cultures rely on implicit communication; low-context cultures are direct', 'Cultural dimensions (power distance, individualism, uncertainty avoidance) help frame differences', 'Cultural self-awareness is the first step to cross-cultural competence'],
      summary: 'Cultural awareness is the foundation of global communication. By understanding the iceberg model, adapting to high-context and low-context styles, and learning cultural dimensions, you can communicate more effectively across cultures and avoid misunderstandings.'
    },
    {
      intro: 'Global communication requires intentional clarity. When you are communicating with people from different cultures, speaking different languages, what seems clear to you may be confusing to them. This lesson covers practical strategies for communicating effectively across linguistic and cultural boundaries.',
      objectives: ['Use clear, simple language in international contexts', 'Avoid idioms, slang, and culturally specific references', 'Be patient with accents and language barriers', 'Confirm understanding to prevent miscommunication'],
      sections: [
        { heading: '1. Clear & Simple Language', paragraphs: ['When communicating globally, use clear, simple language. Choose common words over uncommon ones ("use" instead of "utilize"). Keep sentences short. Avoid jargon, idioms, and culturally specific references. "Hit a home run" means nothing to someone who does not know baseball.', 'Write and speak in a way that is easy to translate. Avoid humor (which often does not translate), sarcasm, and complex metaphors. Use specific numbers instead of approximations ("by Friday at 5 PM" instead of "soon"). Be explicit about expectations.'], bullets: ['Use common words: "use" not "utilize"', 'Short sentences: easier to follow and translate', 'Avoid idioms: "hit a home run," "ballpark figure"', 'Avoid humor and sarcasm: they often do not translate', 'Be specific: "Friday at 5 PM" not "soon"'] },
        { heading: '2. Patience & Confirmation', paragraphs: ['Accents and language barriers require patience. Speak at a moderate pace — not too slow (which can seem condescending) and not too fast. Do not shout (volume does not help understanding). Be willing to repeat or rephrase if needed.', 'Confirm understanding regularly: "Does that make sense?" "Can you summarize what we agreed?" "To make sure I was clear, my main point is..." This is not about testing — it is about ensuring alignment. Encourage questions and create a safe space for people to say they did not understand.'], bullets: ['Moderate pace: not too slow, not too fast', 'Do not shout: volume does not help understanding', 'Be patient: willing to repeat and rephrase', 'Confirm understanding: "Does that make sense?"', 'Create a safe space: encourage questions, no judgment'] },
        { heading: '3. Time Zones & Respect', paragraphs: ['Global teams span time zones. Be respectful of others\' working hours. Use asynchronous communication tools (email, shared documents, project management tools) to reduce the need for real-time meetings. When scheduling meetings, rotate times so the same people are not always at inconvenient hours.', 'Be aware of holidays and cultural events in different regions. A calendar with international holidays helps avoid scheduling meetings on important cultural days. Respect different work styles and communication preferences — adapt without judgment.'], bullets: ['Respect time zones: rotate meeting times', 'Async communication: email, docs, project tools', 'Be aware of international holidays', 'Adapt to different communication preferences', 'Different is not wrong — it is just different'] }
      ],
      keyPoints: ['Use clear, simple language — avoid idioms, jargon, and culturally specific references', 'Be patient with accents and language barriers — confirm understanding', 'Respect time zones and cultural holidays', 'Adapt your communication style without judgment'],
      summary: 'Global communication requires clarity, patience, and respect. By using simple language, being patient with language barriers, confirming understanding, and respecting time zones and cultural differences, you can communicate effectively across the globe.'
    },
    {
      intro: 'Building and leading global teams is one of the most rewarding challenges in modern business. Diverse teams bring diverse perspectives — which leads to better decisions, more innovation, and stronger results. But they also require intentional effort to build trust and alignment across distance and culture.',
      objectives: ['Set clear goals and expectations for global teams', 'Use regular check-ins to maintain alignment', 'Practice inclusive communication', 'Celebrate diversity and build team culture'],
      sections: [
        { heading: '1. Clear Goals & Regular Check-ins', paragraphs: ['Global teams need especially clear goals. When team members are spread across time zones, cultures, and languages, ambiguity is amplified. Define clear objectives, roles, and deadlines. Document decisions and share them in writing.', 'Regular check-ins maintain alignment: weekly team meetings (rotating times), one-on-ones, and async status updates. Use a mix of synchronous (video calls) and asynchronous (updates, docs) communication. Keep a shared document of decisions and action items.'], bullets: ['Clear goals: objectives, roles, and deadlines in writing', 'Document decisions: share for those who could not attend', 'Weekly team meetings: rotate times for fairness', 'One-on-ones: build relationships and address concerns', 'Mix sync and async: video calls + shared docs'] },
        { heading: '2. Inclusive Communication', paragraphs: ['Inclusive communication ensures everyone can participate. Use clear, simple language. Avoid making assumptions about cultural references. Encourage participation from all team members — in some cultures, people are less likely to speak up in meetings. Ask for input directly: "Maria, what is your perspective on this?"', 'Be mindful of language barriers. Do not let native speakers dominate. Acknowledge that communicating in a non-native language is hard. Create multiple channels for input: verbal in meetings, written in documents, and private messages for those who are less comfortable speaking up.'], bullets: ['Use clear, simple language', 'Ask for input directly: "Maria, what is your perspective?"', 'Do not let native speakers dominate', 'Acknowledge: communicating in a non-native language is hard', 'Multiple channels: meeting, document, private message'] },
        { heading: '3. Team Culture & Celebration', paragraphs: ['Global teams need intentional culture-building. Create shared rituals: a team name, a virtual coffee chat, a weekly fun question. Celebrate wins together — even small ones. Recognize contributions publicly. Build personal connections beyond work tasks.', 'Celebrate diversity as a strength. Learn about each other\'s cultures and traditions. Share team members\' cultural celebrations. The most effective global teams are those where differences are valued, not just tolerated — where everyone feels they belong.'], bullets: ['Shared rituals: team name, virtual coffee, fun questions', 'Celebrate wins: small and large, publicly', 'Build personal connections: beyond work tasks', 'Learn about each other\'s cultures', 'Diversity is a strength — value it, do not just tolerate it'] }
      ],
      keyPoints: ['Set clear goals and use regular check-ins to maintain alignment', 'Practice inclusive communication — ensure everyone can participate', 'Build team culture intentionally with shared rituals and celebrations', 'Celebrate diversity — it is a strength, not just something to manage'],
      summary: 'Global teams require intentional effort to succeed. By setting clear goals, communicating inclusively, building team culture, and celebrating diversity, you can create a global team that is cohesive, high-performing, and a great place to work.'
    }
  ];
  existing['com-present'] = [
    {
      intro: 'Great presentations start with great slides. The best slides are not documents — they are visual aids that support your spoken message. The principle of "less is more" applies more to slide design than anywhere else.',
      objectives: ['Design slides with one idea per slide', 'Follow the 10-20-30 rule for presentations', 'Use high-quality visuals, not text-heavy slides', 'Create slides that support, not replace, your spoken message'],
      sections: [
        { heading: '1. One Idea Per Slide', paragraphs: ['Each slide should communicate one single idea. If you have multiple ideas, use multiple slides. This forces you to be clear about what you want to say and makes it easy for the audience to follow.', 'When you put one idea per slide, that idea gets the audience\'s full attention. It also makes your presentation easy to navigate — if someone asks a question about a specific point, you can go back to that slide.'], bullets: ['One idea per slide: clarity and focus', 'Multiple ideas = multiple slides', 'Forces clarity: what is the ONE thing this slide says?', 'Full attention: the audience focuses on one idea at a time', 'Easy to navigate: reference specific slides for Q&A'] },
        { heading: '2. The 10-20-30 Rule', paragraphs: ['Guy Kawasaki\'s 10-20-30 rule: 10 slides (the ideal maximum for a presentation), 20 minutes (the longest you should speak), and 30-point font (the minimum font size). This rule forces focus, discipline, and clarity.', '10 slides forces you to prioritize. 20 minutes respects the audience\'s attention span. 30-point font prevents you from putting too much text on a slide. Adapt the rule to your context, but the principle holds: keep it short, focused, and visual.'], bullets: ['10 slides: maximum — forces prioritization', '20 minutes: longest you should speak', '30-point font: minimum — prevents text overload', 'Adapt to context, but keep the principle', 'Short, focused, and visual'] },
        { heading: '3. Visuals & Minimal Text', paragraphs: ['Slides are visual aids, not documents. Use high-quality images, diagrams, charts, and short phrases. Never put your full script on slides. The audience should be listening to you, not reading your slides. Use slides to reinforce key points visually.', 'Minimal text: 6 words per bullet, 6 bullets per slide maximum. Use keywords, not full sentences. If you need to provide detailed information, create a handout. The presentation is for the spoken message; the handout is for the details.'], bullets: ['Slides are visual aids, not documents', 'High-quality images, diagrams, charts', 'Never put your full script on slides', '6 words per bullet, 6 bullets per slide max', 'Detailed info = handout; slides = spoken message'] }
      ],
      keyPoints: ['One idea per slide — clarity and focus', '10-20-30 rule: 10 slides, 20 minutes, 30-point font', 'Slides are visual aids — use high-quality visuals, not text', 'Minimal text: keywords, not full sentences'],
      summary: 'Slide design is about clarity, not decoration. By following the principle of one idea per slide, applying the 10-20-30 rule, using visuals, and keeping text minimal, you create slides that support your message — not compete with it.'
    },
    {
      intro: 'Data alone is boring. To make data compelling, you need to frame it within a narrative that gives it context and meaning. Storytelling with data is the skill of turning numbers into insights that drive action.',
      objectives: ['Frame data with context and narrative', 'Highlight key insights, not every data point', 'Choose the right chart for your message', 'Make data accessible and actionable'],
      sections: [
        { heading: '1. Context is Everything', paragraphs: ['Data without context is meaningless. "Revenue was $10M" — is that good or bad? Context tells you: compared to last year, compared to budget, compared to competitors. Always provide context that helps the audience understand what the data means.', 'Frame data in human terms. Instead of "Customer satisfaction increased by 2%," say "Our customer satisfaction score is now at 92%, which means 9 out of 10 customers would recommend us." Make the abstract concrete and relatable.'], bullets: ['Context: compare to last year, budget, or competitors', 'Data without context is meaningless', 'Human terms: translate numbers into relatable concepts', 'Make abstract concrete: "9 out of 10 customers..."', 'Frame data around the audience\'s interests'] },
        { heading: '2. Highlighting Key Insights', paragraphs: ['Do not show every data point. Highlight the key insights — the findings that matter. Use callouts, color, and annotations to draw attention to the most important numbers. "The key takeaway here is..."', 'Guide the audience through the data. Do not just show a chart and expect them to figure it out. Tell them what to look for and what it means. The three steps: Tell them what they are looking at, highlight the key insight, and explain why it matters.'], bullets: ['Highlight key insights, not every data point', 'Use callouts, color, and annotations', 'Guide the audience: what to look for, what it means', 'Three steps: tell, highlight, explain', 'Less is more: one insight per data slide'] },
        { heading: '3. Choosing the Right Chart', paragraphs: ['Bar chart: compare categories (revenue by region). Line chart: show trends over time (monthly sales). Pie chart: show proportions (market share) — use sparingly, as humans are bad at comparing angles. Scatter plot: show correlation between two variables (price vs demand).', 'Chart design tips: label directly (not just a legend), start y-axis at 0 (to avoid misleading charts), use consistent colors, remove unnecessary gridlines and 3D effects. The best chart is the one that makes the insight immediately obvious.'], bullets: ['Bar chart: compare categories', 'Line chart: trends over time', 'Pie chart: proportions (use sparingly)', 'Scatter plot: correlations', 'Label directly, start y-axis at 0, remove clutter', 'The best chart makes the insight obvious'] }
      ],
      keyPoints: ['Always provide context — data without context is meaningless', 'Highlight key insights, not every data point', 'Guide the audience: tell them what to look for and what it means', 'Choose the right chart type and design it for clarity'],
      summary: 'Storytelling with data is about transforming numbers into narratives. By providing context, highlighting key insights, and choosing the right visualizations, you can make data compelling, accessible, and actionable.'
    },
    {
      intro: 'Q&A is often the most important part of a presentation. It is where the audience engages deeply, where you demonstrate expertise, and where the real persuasion happens. A strong Q&A can salvage a mediocre presentation — and a weak one can undermine a great one.',
      objectives: ['Anticipate questions and prepare answers', 'Stay calm when you do not know the answer', 'Handle difficult questions professionally', 'Use Q&A to reinforce your key message'],
      sections: [
        { heading: '1. Anticipating Questions', paragraphs: ['Before any presentation, anticipate the questions you are likely to receive. Think about what might be unclear, controversial, or challenging. Prepare answers for the top 5-10 questions. Practice them aloud.', 'Prepare for different types of questions: clarifying questions (about your content), challenging questions (that push back on your conclusions), and curveball questions (unexpected or off-topic). Have a strategy for each type.'], bullets: ['Anticipate: what questions are likely?', 'Prepare answers for top 5-10 questions', 'Practice answers aloud', 'Clarifying: about your content', 'Challenging: push back on conclusions', 'Curveball: unexpected or off-topic'] },
        { heading: '2. Handling Difficult Questions', paragraphs: ['When you receive a difficult question, stay calm. Do not get defensive. Take a breath. Thank the person for the question. If you need a moment to think, say "That is a great question. Let me think about that."', 'If you do not know the answer, be honest: "I do not have that information at hand, but I will follow up with you after the presentation." Never bluff — getting caught in a lie destroys your credibility. Offer to connect them with someone who knows or send the information later.'], bullets: ['Stay calm: do not get defensive', 'Take a breath and thank the questioner', 'Buy time: "That is a great question. Let me think..."', 'If you do not know: "I will follow up with you"', 'Never bluff — honesty preserves credibility'] },
        { heading: '3. Using Q&A to Reinforce Your Message', paragraphs: ['Q&A is an opportunity to reinforce your key message. When answering, connect back to your main points. "That is a great question, and it ties back to my earlier point about..."', 'Bridge from difficult questions to your message. "I understand your concern about the timeline. What I want to emphasize is that the quality of the outcome is our priority, which is why we are taking this approach." Always steer the conversation back to your core narrative.'], bullets: ['Connect answers back to your main message', 'Bridge: acknowledge the concern, then reframe', 'Reinforce: Q&A is another chance to make your point', 'Thank questioners: it shows confidence and respect', 'End Q&A with a strong closing statement'] }
      ],
      keyPoints: ['Anticipate questions and prepare answers in advance', 'Stay calm, do not bluff, and be honest when you do not know', 'Use Q&A to reinforce your key message, not just answer questions', 'Bridge from difficult questions back to your core narrative'],
      summary: 'Q&A is a skill that can be prepared for. By anticipating questions, handling difficult ones with grace, and using answers to reinforce your message, you can turn Q&A into one of the most powerful parts of your presentation.'
    }
  ];
  existing['com-listening'] = [
    {
      intro: 'Listening is the most underrated communication skill. Most people listen to reply — they are formulating their response while the other person is still speaking. Real listening is listening to understand. It is rare, valuable, and transformative.',
      objectives: ['Understand the difference between listening to reply and listening to understand', 'Recognize the benefits of deep listening', 'Identify common listening barriers', 'Commit to being the exception — a real listener'],
      sections: [
        { heading: '1. Listening to Reply vs Listening to Understand', paragraphs: ['When you listen to reply, you are not really listening — you are waiting for your turn to talk. You are preparing your response, finding counterarguments, or thinking about how to relate the conversation to yourself. This is the default mode for most people.', 'Listening to understand is different. You are fully present, focused on the speaker\'s words, tone, and body language. You are trying to see the world from their perspective. You ask questions to deepen your understanding, not to score points. This is rare — and it is how trust is built.'], bullets: ['Listening to reply: preparing your response, not listening', 'Listening to understand: fully present, focused on the speaker', 'Default mode: most people listen to reply', 'Real listening: trying to understand, not to respond', 'Rare and valuable: it is how trust is built'] },
        { heading: '2. The Benefits of Deep Listening', paragraphs: ['Deep listening transforms relationships. When people feel truly heard, they trust you more, they open up more, and they are more willing to listen to you in return. It reduces misunderstandings, resolves conflicts, and deepens connections.', 'In professional settings, listening well makes you more effective. You understand problems better, build stronger teams, and make better decisions because you have more complete information. Leaders who listen are more respected and more influential.'], bullets: ['Builds trust: people feel heard and valued', 'Reduces misunderstandings: you actually understand', 'Deepens connections: personal and professional', 'Better decisions: more complete information', 'More effective leaders: respected and influential'] },
        { heading: '3. Barriers to Listening', paragraphs: ['Common barriers: distractions (phone, notifications, environment), assumptions (thinking you already know what they will say), emotional triggers (words that provoke an emotional reaction), and ego (wanting to be right, wanting to share your story).', 'Overcome barriers: put away your phone, maintain eye contact, check your assumptions, and consciously set the intention to understand. "My goal in this conversation is to understand their perspective" is a powerful intention that changes how you listen.'], bullets: ['Distractions: phone, notifications, environment', 'Assumptions: thinking you already know', 'Emotional triggers: words that provoke a reaction', 'Ego: wanting to be right, wanting to share your story', 'Overcome: put away phone, set intention to understand'] }
      ],
      keyPoints: ['Most people listen to reply — real listening is listening to understand', 'Deep listening builds trust, reduces misunderstandings, and deepens connections', 'Barriers: distractions, assumptions, emotional triggers, ego', 'Set the intention to understand — it transforms how you listen'],
      summary: 'Listening is the most powerful communication skill. By moving from "listening to reply" to "listening to understand," you build deeper trust, make better decisions, and become the kind of person others want to talk to.'
    },
    {
      intro: 'Active listening is a set of techniques that help you listen more effectively. It is not just about hearing words — it is about engaging with the speaker, confirming understanding, and showing that you care. These techniques can be learned and practiced.',
      objectives: ['Use paraphrasing to confirm understanding', 'Ask questions that deepen understanding', 'Avoid interrupting — let the speaker finish', 'Apply the SOLER framework for focused listening'],
      sections: [
        { heading: '1. Paraphrasing', paragraphs: ['Paraphrasing is restating what the speaker said in your own words. It serves two purposes: it confirms you understood correctly, and it makes the speaker feel heard. "So what I am hearing is that you are frustrated because the deadline was moved up without notice."', 'If your paraphrase is wrong, the speaker can correct you. If it is right, they feel understood. This simple technique is one of the most powerful tools in communication. It prevents misunderstandings before they happen.'], bullets: ['Paraphrase: restate in your own words', 'Confirms understanding: "So what I am hearing is..."', 'Makes the speaker feel heard', 'Allows correction if you misunderstood', 'Prevents misunderstandings before they happen'] },
        { heading: '2. Asking Questions', paragraphs: ['Questions deepen your understanding and show you are engaged. Open-ended questions (that cannot be answered with yes/no) encourage the speaker to elaborate: "What was that like for you?" "How did you handle that?" "What do you think is the best way forward?"', 'Follow-up questions show you are paying attention: "You mentioned the team was under pressure — can you tell me more about that?" Avoid leading questions that push your agenda: "Don\'t you think you should have..." Instead, ask neutral questions that explore their perspective.'], bullets: ['Open-ended questions: encourage elaboration', 'Follow-up questions: show you are paying attention', 'Neutral questions: explore their perspective, not your agenda', 'Avoid: leading questions, "why" questions (can feel accusatory)', 'Questions are a sign of engagement, not ignorance'] },
        { heading: '3. SOLER & Avoiding Interruptions', paragraphs: ['SOLER is a framework for non-verbal listening: Sit squarely (face the person), Open posture (uncross arms and legs), Lean in (slightly forward shows engagement), Eye contact (maintain appropriately), and Relax (be natural, not rigid). This posture signals that you are fully present.', 'Do not interrupt. Let the speaker finish their thought before you respond. Even if you are excited to share something, wait. An interruption tells the speaker that what you have to say is more important than what they are saying. Silence after they finish is okay — it means you are thinking, which is a compliment.'], bullets: ['SOLER: Sit, Open, Lean, Eye, Relax', 'Non-verbal engagement: body language shows you are listening', 'Do not interrupt: let the speaker finish', 'Your turn will come — waiting shows respect', 'Silence after they finish is okay — it shows you are thinking'] }
      ],
      keyPoints: ['Paraphrasing confirms understanding and makes the speaker feel heard', 'Open-ended and follow-up questions deepen understanding', 'SOLER framework: non-verbal signals of engaged listening', 'Do not interrupt — let the speaker finish, then pause before responding'],
      summary: 'Active listening is a skill that can be practiced. By using paraphrasing, asking thoughtful questions, applying the SOLER framework, and resisting the urge to interrupt, you become a listener who truly understands — and that is a rare and valuable gift.'
    },
    {
      intro: 'Empathy is the ability to understand and share the feelings of another. It is the foundation of deep human connection. In practice, empathy is not about fixing problems — it is about being present with someone in their experience.',
      objectives: ['Distinguish empathy from sympathy and problem-solving', 'Practice validating emotions', 'Use empathetic phrases', 'Be present without trying to fix'],
      sections: [
        { heading: '1. Empathy vs Sympathy vs Fixing', paragraphs: ['Sympathy is feeling FOR someone from a distance: "I feel sorry for you." Empathy is feeling WITH someone: "I am with you in this." The difference is connection. Empathy is a shared experience; sympathy is a separate observation.', 'Fixing is the urge to solve the problem. When someone shares a struggle, the natural response is often to offer advice. But most people do not want solutions — they want to be heard. Before offering advice, ask: "Do you want my perspective, or do you just need me to listen?"'], bullets: ['Sympathy: feeling for someone from a distance', 'Empathy: feeling with someone — shared experience', 'Fixing: jumping to solutions before understanding', 'Most people want to be heard, not fixed', 'Ask: "Do you want my perspective or just need me to listen?"'] },
        { heading: '2. Validating Emotions', paragraphs: ['Validation is acknowledging someone\'s feelings as real and understandable. You do not have to agree with their perspective — you just acknowledge their experience. "That sounds really difficult." "I can see why you would feel that way." "It makes sense that you are frustrated."', 'Validation does not mean agreement. You can validate someone\'s feelings while disagreeing with their actions. "I understand why you are angry. At the same time, I think we need to consider..." This is empathy without enabling. It maintains the relationship while addressing the issue.'], bullets: ['Validation: acknowledging feelings as real and understandable', 'You do not have to agree — just acknowledge', 'Phrases: "That sounds really difficult"', 'Validation is not agreement', 'Validate feelings, then address the issue'] },
        { heading: '3. The Power of Presence', paragraphs: ['Sometimes the most empathic thing you can do is simply be present. Not talking, not solving, not advising — just being there. Sitting with someone in their pain without trying to fix it is a profound act of caring.', 'Avoid phrases that minimize feelings: "At least it could be worse," "Everything happens for a reason," "Just think positive." These are often well-intentioned but they invalidate the person\'s experience. Instead, just be present and listen. That is enough.'], bullets: ['Presence: being with someone without fixing', 'Sometimes silence is the most powerful response', 'Avoid: "At least...", "Everything happens for a reason"', 'These phrases invalidate, even if well-intentioned', 'Just being present and listening is enough'] }
      ],
      keyPoints: ['Empathy is feeling WITH someone, not FOR them (sympathy) or fixing them', 'Validation acknowledges feelings as real — without necessarily agreeing', 'Most people want to be heard, not fixed — ask before advising', 'Sometimes the most powerful empathy is simply being present'],
      summary: 'Empathy is the art of being present with another person\'s experience. By distinguishing empathy from sympathy and fixing, validating emotions, and simply being present, you can offer the kind of connection that heals, strengthens, and deepens relationships.'
    }
  ];
  existing['com-feedback'] = [
    {
      intro: 'Feedback is the fuel of growth. Without it, we operate in the dark, never knowing what we are doing well or where we can improve. Yet many people fear giving feedback (it feels like criticism) and receiving it (it feels like an attack). Changing this mindset is transformative.',
      objectives: ['Understand why feedback is essential for growth', 'Shift from seeing feedback as criticism to seeing it as a gift', 'Seek feedback regularly from multiple sources', 'Create a culture of feedback in your teams'],
      sections: [
        { heading: '1. Feedback Fuels Growth', paragraphs: ['Feedback is information about how we are perceived and how our actions affect others. It is the only way to know if our self-perception matches reality. Without feedback, we repeat mistakes and miss opportunities to improve.', 'Think of feedback as a gift: someone cared enough to tell you something that could help you grow. It is not about finding fault — it is about closing the gap between where you are and where you want to be. The most successful people actively seek feedback.'], bullets: ['Feedback: information about perception and impact', 'Without it: we repeat mistakes, miss opportunities', 'Feedback is a gift: someone invested in your growth', 'Not about fault — about closing the gap', 'Successful people actively seek feedback'] },
        { heading: '2. Seek Feedback Regularly', paragraphs: ['Do not wait for annual reviews. Seek feedback regularly: after a project, a meeting, or a presentation. Ask specific questions: "What is one thing I could have done better in that meeting?" "What is a strength you see in me that I should leverage more?"', 'Ask multiple people for feedback — different perspectives give a fuller picture. And ask for feedback on specific behaviors, not general traits. "How was my presentation?" is less useful than "How was my pacing during the presentation?"'], bullets: ['Seek regularly: after projects, meetings, presentations', 'Specific questions: "What could I have done better?"', 'Multiple sources: different perspectives', 'Ask about behaviors, not general traits', 'Feedback is a muscle: practice seeking it'] },
        { heading: '3. Creating a Feedback Culture', paragraphs: ['In teams, make feedback a normal, expected part of how you work. Start meetings with a quick feedback round. Model giving and receiving feedback openly. When leaders ask for feedback and act on it, it sets the tone for everyone.', 'Normalize receiving feedback gracefully: "Thank you, I appreciate that." Do not get defensive, explain, or justify. Just listen, thank, and reflect. The more gracefully you receive feedback, the more people will give it to you — and that is how you grow.'], bullets: ['Make feedback normal: regular, expected, structured', 'Model it: leaders ask for and act on feedback', 'Normalize receiving: "Thank you, I appreciate that"', 'Do not get defensive: listen, thank, reflect', 'The more gracefully you receive, the more you will get'] }
      ],
      keyPoints: ['Feedback is essential for growth — it is a gift, not criticism', 'Seek feedback regularly from multiple sources', 'Ask specific behavioral questions', 'Create a feedback culture by modeling graceful receiving and acting on feedback'],
      summary: 'Feedback is the fuel of personal and professional growth. By shifting your mindset to see it as a gift, seeking it regularly, and creating a culture where it is expected and valued, you unlock continuous improvement for yourself and your team.'
    },
    {
      intro: 'The SBI model (Situation, Behavior, Impact) is a structured framework for giving feedback that is clear, specific, and non-judgmental. It focuses on observable behavior and its effects, making feedback easier to give and easier to receive.',
      objectives: ['Apply the SBI model: Situation, Behavior, Impact', 'Describe specific behaviors, not personality traits', 'Focus on observable facts, not interpretations', 'Give feedback that is actionable and constructive'],
      sections: [
        { heading: '1. The SBI Model', paragraphs: ['SBI stands for: Situation (where and when the behavior occurred), Behavior (the specific, observable action you observed), and Impact (the effect of that behavior on you, the team, or the outcome).', 'Example: "In yesterday\'s client meeting (Situation), when you interrupted the client twice (Behavior), it made them feel rushed and they did not share their full requirements (Impact)." This is specific, factual, and focused on the impact — not the person\'s character.'], bullets: ['Situation: where and when did it happen?', 'Behavior: what specific, observable action did you see?', 'Impact: what was the effect on you, the team, or the outcome?', 'Example: "In yesterday\'s meeting, when you interrupted, it made the client feel rushed"', 'SBI is specific, factual, and non-judgmental'] },
        { heading: '2. Focusing on Behavior, Not Personality', paragraphs: ['The key to effective feedback is describing specific behaviors, not labeling the person. Instead of "You are disorganized" (personality label), say "In the last two team meetings, you arrived without your notes and had to ask for copies" (behavior).', 'Behavior is observable and can be changed. Personality feels fixed and generates defensiveness. When you describe behavior, the person can do something about it. When you label personality, they feel attacked and shut down.'], bullets: ['Behavior: observable, changeable, specific', 'Personality: fixed label, generates defensiveness', 'Instead of "You are disorganized," describe the behavior', 'Behavior can be changed; personality feels attacked', 'Focus on behavior to make feedback actionable'] },
        { heading: '3. Making Feedback Constructive', paragraphs: ['Constructive feedback is feedback that helps the person improve. It is specific, timely, and focused on the future. It is not about blame — it is about development. "In the future, could you share your notes before the meeting so everyone can prepare?"', 'Balance positive and constructive feedback. Do not just give feedback when something is wrong. Notice and acknowledge what is going well too. Positive reinforcement is more motivating than criticism. A ratio of 5:1 positive to constructive feedback is ideal for maintaining motivation.'], bullets: ['Constructive: specific, timely, future-focused', 'Not about blame — about development', 'Balance: 5:1 positive to constructive', 'Acknowledge what is going well', 'Feedback is about helping the person grow'] }
      ],
      keyPoints: ['SBI model: Situation, Behavior, Impact — gives specific, non-judgmental feedback', 'Describe specific behaviors, not personality traits', 'Constructive feedback is specific, timely, and future-focused', 'Balance positive and constructive feedback — 5:1 ratio'],
      summary: 'The SBI model provides a clear, structured approach to giving feedback. By focusing on specific situations, observable behaviors, and their impact, you can give feedback that is constructive, actionable, and more likely to be received well.'
    },
    {
      intro: 'Receiving feedback is a skill — and it is harder than giving it. Our natural reaction to criticism is defensiveness. But the ability to receive feedback gracefully is what separates those who grow from those who stay stuck. This lesson covers how to receive feedback effectively.',
      objectives: ['Listen without defensiveness', 'Ask clarifying questions to understand', 'Thank the giver for their input', 'Reflect and decide what to act on'],
      sections: [
        { heading: '1. Listen Without Defensiveness', paragraphs: ['When you receive feedback, your first instinct may be to defend, explain, or justify. Fight this instinct. Instead, take a breath and simply listen. Your goal is to understand the other person\'s perspective, not to prove them wrong.', 'Remember: feedback is information. It is someone\'s perception of reality. It may not be 100% accurate, but it is 100% true from their perspective. Your job is to understand that perspective, not to argue with it. You can decide later whether to act on it.'], bullets: ['Resist defensiveness: do not explain, justify, or argue', 'Goal: understand their perspective, not prove them wrong', 'Feedback is information — someone\'s perception of reality', 'It is 100% true from their perspective', 'Listen first, decide later'] },
        { heading: '2. Ask Clarifying Questions', paragraphs: ['After listening, ask questions to deepen your understanding. "Can you give me a specific example?" "What would you like me to do differently?" "How did that behavior affect you?" Questions show you are taking the feedback seriously and help you understand exactly what to work on.', 'Avoid asking "why" questions that sound defensive: "Why do you think that?" can sound like you are challenging the feedback. Instead, ask "what" and "how" questions: "What specifically did you notice?" "How could I handle that better?"'], bullets: ['Ask for examples: "Can you give me a specific example?"', 'Ask for suggestions: "What would you like me to do differently?"', 'Ask about impact: "How did that affect you?"', 'Avoid "why" questions: can sound defensive', 'Ask "what" and "how" questions'] },
        { heading: '3. Thank, Reflect, Decide', paragraphs: ['Always thank the person for their feedback. "Thank you for telling me that. I appreciate you taking the time." This does not mean you agree with everything — it means you value their input and the courage it took to share it.', 'After receiving feedback, take time to reflect. Do not make a decision in the moment. Consider: Is this feedback accurate? Is it useful? What would change if I acted on it? Then decide what to do: implement the change, seek additional perspectives, or consciously decide not to act on it. The key is that you made a conscious choice, not a defensive reaction.'], bullets: ['Thank: "Thank you for telling me, I appreciate it"', 'Thanking does not mean agreeing — it means valuing the input', 'Reflect: is it accurate? Is it useful?', 'Decide: implement, seek more perspectives, or consciously not act', 'Make a conscious choice, not a defensive reaction'] }
      ],
      keyPoints: ['Listen without defensiveness — your goal is to understand', 'Ask clarifying questions: examples, suggestions, impact', 'Always thank the giver — it encourages future feedback', 'Reflect and decide consciously — do not react defensively'],
      summary: 'Receiving feedback gracefully is a superpower. By listening without defensiveness, asking clarifying questions, thanking the giver, and reflecting before deciding how to act, you turn feedback into one of your most powerful tools for growth.'
    }
  ];
  existing['com-digital'] = [
    {
      intro: 'Your online presence is your digital brand — it is how the world sees you when they search for you online. In today\'s connected world, your digital presence can be as important as your resume. Building a positive, professional online presence opens doors to opportunities.',
      objectives: ['Understand the importance of your digital presence', 'Build a consistent personal brand across platforms', 'Share valuable content that showcases your expertise', 'Engage authentically with your online community'],
      sections: [
        { heading: '1. Your Digital Presence is Your Brand', paragraphs: ['When someone searches for your name, what do they find? A professional LinkedIn profile, thoughtful content, and positive engagement? Or old social media posts, nothing at all, or someone else with the same name? Your digital presence is your reputation online.', 'A strong digital presence: showcases your expertise (you share what you know), demonstrates your values (what you share says about you), helps you connect (with opportunities and people), and is consistent (your message is aligned across platforms). Invest in your digital presence — it is the modern equivalent of a professional reputation.'], bullets: ['Your digital presence = your online reputation', 'A strong presence: showcases expertise, demonstrates values', 'Opens doors: opportunities, connections, visibility', 'Consistency: aligned message across platforms', 'Invest in it: it is your professional reputation'] },
        { heading: '2. Consistency Across Platforms', paragraphs: ['Your personal brand should be consistent across platforms: LinkedIn (professional, long-form content), Twitter (thought leadership, industry conversations), Instagram (visual, behind-the-scenes), and your personal website/portfolio (central hub).', 'Consistency does not mean posting the same thing everywhere — it means having a consistent professional identity: similar profile photo, consistent bio, aligned topics, and coherent messaging. Each platform has its own style, but the person behind them should be clearly the same.'], bullets: ['LinkedIn: professional, long-form, industry content', 'Twitter: thought leadership, short-form, conversations', 'Instagram: visual, behind-the-scenes, personal', 'Website: central hub, portfolio, bio', 'Consistency: photo, bio, message, values'] },
        { heading: '3. Sharing Value & Engaging Authentically', paragraphs: ['Share content that educates, entertains, or inspires your audience. It is not about self-promotion — it is about adding value. Share what you have learned, insights from your work, and perspectives on your industry. Over time, this builds credibility and a following.', 'Engage authentically: comment on others\' posts, participate in conversations, share others\' content with your own commentary. Building relationships is more important than building followers. Authentic engagement — being genuinely helpful and interested in others — is the foundation of a strong digital presence.'], bullets: ['Share value: educate, entertain, inspire', 'Not self-promotion — adding value', 'Build credibility: share insights and perspectives', 'Engage authentically: comment, participate, share', 'Relationships > followers — genuine connections matter'] }
      ],
      keyPoints: ['Your digital presence is your online reputation — invest in it', 'Be consistent across platforms: photo, bio, message, values', 'Share content that adds value — educate, entertain, inspire', 'Engage authentically — relationships matter more than followers'],
      summary: 'Your digital presence is a powerful part of your professional identity. By building a consistent brand, sharing valuable content, and engaging authentically, you can create an online presence that opens doors and builds your reputation.'
    },
    {
      intro: 'Content creation is how you share your expertise and build your audience. Whether you are writing, filming, or recording, the principles of creating content that resonates are the same: provide value, be consistent, and prioritize quality.',
      objectives: ['Create content that educates, entertains, or inspires', 'Use a content calendar to stay organized', 'Prioritize quality over quantity', 'Repurpose content across platforms'],
      sections: [
        { heading: '1. Content That Resonates', paragraphs: ['The best content does one of three things: educates (teaches something new), entertains (engages and delights), or inspires (motivates action or change). Ask yourself: "What value does this content provide?" If you cannot answer clearly, do not publish it.', 'Know your audience: what do they care about? What problems do they have? What do they want to learn? Create content that serves them, not content that serves your ego. The most successful creators are generous with their knowledge.'], bullets: ['Educates: teaches something new', 'Entertains: engages and delights', 'Inspires: motivates action or change', 'Know your audience: what do they care about?', 'Serve your audience, not your ego'] },
        { heading: '2. Consistency & Content Calendar', paragraphs: ['Consistency is more important than frequency. It is better to post once a week consistently than to post daily for a week and then disappear for a month. A content calendar helps you plan, stay organized, and avoid last-minute scrambling.', 'Your content calendar should include: topics, formats (article, video, post), publishing dates, and platforms. Plan in batches — create a month\'s worth of content in a few focused sessions. This is more efficient than creating content day by day.'], bullets: ['Consistency > frequency: regular beats sporadic', 'Content calendar: plan topics, formats, dates, platforms', 'Batch create: a month\'s content in a few sessions', 'Stay organized: avoid last-minute scrambling', 'Repurpose: turn one piece into multiple formats'] },
        { heading: '3. Quality Over Quantity', paragraphs: ['One great piece of content is worth more than ten mediocre ones. A well-researched, well-written article that provides real value will be shared, remembered, and linked to. A rushed, shallow post will be ignored.', 'Spend time on quality: research your topic, craft your headline, edit ruthlessly, and design for readability. A single high-quality piece can generate value for months or years. Ask yourself: "Would I share this? Would I want my name on this?" If the answer is no, keep working on it.'], bullets: ['One great piece > ten mediocre ones', 'Quality is remembered and shared', 'Invest time in research, writing, editing, design', '"Would I share this?" — if no, keep working', 'High-quality content has lasting value'] }
      ],
      keyPoints: ['Create content that educates, entertains, or inspires', 'Use a content calendar for consistency — batch create', 'Quality over quantity — one great piece is worth more than ten mediocre ones', 'Repurpose content across platforms for maximum reach'],
      summary: 'Content creation is a powerful way to build your brand and share your expertise. By creating value-driven content, staying consistent with a content calendar, and prioritizing quality, you can build an audience that trusts and respects your voice.'
    },
    {
      intro: 'Online communities are where conversations happen, relationships are built, and opportunities are discovered. Whether it is LinkedIn, Twitter, a niche forum, or a Slack group, being part of the right communities amplifies your growth.',
      objectives: ['Join communities where your audience is active', 'Give value before asking for anything', 'Build genuine relationships, not just followers', 'Contribute regularly and authentically'],
      sections: [
        { heading: '1. Finding Your Communities', paragraphs: ['The best communities are where your target audience already spends time. For professionals: LinkedIn groups, industry forums, Slack communities. For creatives: Behance, Dribbble, Instagram. For developers: GitHub, Stack Overflow, Dev.to.', 'Do not join too many communities at once. Pick 2-3 where you can be active and contribute meaningfully. It is better to be a valuable member of a few communities than a passive member of many. Quality of engagement matters more than quantity.'], bullets: ['LinkedIn groups: professional discussions', 'Industry forums: niche expertise', 'Slack communities: real-time conversations', 'Creative platforms: Behance, Dribbble, Instagram', 'Developer communities: GitHub, Stack Overflow', 'Pick 2-3: be active and valuable'] },
        { heading: '2. Give Value First', paragraphs: ['The golden rule of online communities: give value before you ask for anything. Answer questions, share resources, provide feedback, and be helpful. When you are known as someone who gives, people will be happy to help you when you need it.', 'Do not join a community and immediately promote yourself or your work. This is seen as spammy and damages your reputation. Spend time observing, understanding the community norms, and contributing before you ever ask for anything.'], bullets: ['Give value first: answer questions, share resources', 'Be helpful: provide feedback, share insights', 'Build reputation: known as a giver, not a taker', 'Do not promote immediately: observe and contribute first', 'Understand community norms before posting'] },
        { heading: '3. Build Relationships, Not Just Followers', paragraphs: ['Online communities are about relationships, not metrics. A follower count means nothing if you have no genuine connections. Focus on having real conversations, not just broadcasting your content.', 'Engage with others\' content meaningfully. Comment with insights, not just "Great post!" Send direct messages to people you admire. Schedule virtual coffee chats. The strongest professional relationships are built one conversation at a time — online and offline.'], bullets: ['Relationships > followers: genuine connections matter', 'Engage meaningfully: insights, not just "Great post!"', 'Reach out directly: DMs, virtual coffee chats', 'One conversation at a time: build relationships gradually', 'The strongest relationships are built authentically'] }
      ],
      keyPoints: ['Join 2-3 communities where your audience is active', 'Give value before asking for anything — build your reputation', 'Build relationships, not just followers', 'Engage authentically: meaningful conversations, not broadcasting'],
      summary: 'Online communities are where professional relationships are built. By finding the right communities, giving value first, and focusing on genuine relationships over metrics, you can build a network that supports your growth and opens doors to opportunities.'
    }
  ];
  window.COURSE_DETAILS = existing;
})();
